package com.votehub.controller;
import com.votehub.security.AuthService;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/auth") @CrossOrigin(origins="http://localhost:5173") public class AuthController {final AuthService s;AuthController(AuthService x){s=x;} record Voter(String voterId,String fullName,LocalDate dob,String aadhaar,String email,String mobile,String password){} record Admin(String employeeId,String fullName,String email,String mobile,String password){} record Verify(String id,String otp){} record Login(String id,String password){}
@PostMapping("/register/voter") public Map<String,Object> voter(@RequestBody Voter r){String otp=s.registerVoter(r.voterId,r.fullName,r.dob,r.aadhaar,r.email,r.mobile,r.password);return Map.of("message","Account created. Verify OTP.","demoOtp",otp);}
@PostMapping("/register/admin") public Map<String,Object> admin(@RequestBody Admin r){String otp=s.registerAdmin(r.employeeId,r.fullName,r.email,r.mobile,r.password);return Map.of("message","Admin account created. Verify OTP.","demoOtp",otp);}
@PostMapping("/verify") public Map<String,Object> verify(@RequestBody Verify r){s.verify(r.id,r.otp);return Map.of("message","Account verified successfully");}
@PostMapping("/login") public Map<String,Object> login(@RequestBody Login r){var t=s.login(r.id,r.password);var u=s.user(t);return Map.of("token",t,"role",u.role.toString(),"name",u.fullName,"id",u.id);}
@GetMapping("/me") public Map<String,Object> me(@RequestHeader("Authorization") String h){var u=s.user(h.replace("Bearer ",""));return Map.of("id",u.id,"role",u.role.toString(),"name",u.fullName,"voterId",Objects.toString(u.voterId,""),"employeeId",Objects.toString(u.employeeId,""),"email",u.email,"mobile",u.mobile,"verified",u.verified);}}
